package com.greenocean.backend.professional.service;
import com.greenocean.backend.common.exception.*;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import java.time.*;import java.util.*;
@Service @Transactional
public class ProfessionalScheduling {
 private final JdbcTemplate db;private final ProfessionalAuthority auth;private final int lead;private final com.greenocean.backend.identity.AccessPolicy access;
 public ProfessionalScheduling(JdbcTemplate db,ProfessionalAuthority auth,com.greenocean.backend.identity.AccessPolicy access,@Value("${greenocean.clinic.minimum-lead-minutes:15}")int lead){this.db=db;this.auth=auth;this.access=access;this.lead=Math.max(1,Math.min(1440,lead));}
 public record Slot(@jakarta.validation.constraints.NotNull Instant startsAt,@jakarta.validation.constraints.NotNull Instant endsAt,@jakarta.validation.constraints.Pattern(regexp="TEXT|AUDIO|VIDEO") @jakarta.validation.constraints.NotNull String mode,@jakarta.validation.constraints.Min(0) @jakarta.validation.constraints.Max(1000000000000L)long priceUnits,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=80)String timezone,boolean publish){}
 public record Rule(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=80)String timezone,@jakarta.validation.constraints.Min(1) @jakarta.validation.constraints.Max(7)int weekday,@jakarta.validation.constraints.NotBlank String startsLocal,@jakarta.validation.constraints.NotBlank String endsLocal,@jakarta.validation.constraints.NotNull LocalDate validFrom,@jakarta.validation.constraints.NotNull LocalDate validUntil,@jakarta.validation.constraints.Min(15) @jakarta.validation.constraints.Max(240)int slotMinutes,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Pattern(regexp="TEXT|AUDIO|VIDEO")String mode,@jakarta.validation.constraints.Min(0) @jakarta.validation.constraints.Max(1000000000000L)long priceUnits,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Pattern(regexp="EARLIER|LATER|REJECT")String overlapPolicy){}
 public record ExceptionWindow(@jakarta.validation.constraints.NotNull Instant startsAt,@jakarta.validation.constraints.NotNull Instant endsAt,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=300)String reason){}
 public UUID slot(UUID who,Slot in){auth.owner(who);auth.lock(who);return insert(who,in,null);}
 private UUID insert(UUID who,Slot in,UUID rule){ZoneId.of(in.timezone());if(in.startsAt()==null||in.endsAt()==null||in.startsAt().isBefore(Instant.now().plusSeconds(lead*60L))||!in.endsAt().isAfter(in.startsAt())||Duration.between(in.startsAt(),in.endsAt()).toMinutes()<15||Duration.between(in.startsAt(),in.endsAt()).compareTo(Duration.ofHours(8))>0||in.priceUnits()<0||in.priceUnits()>1000000000000L||!Set.of("TEXT","AUDIO","VIDEO").contains(in.mode()))throw new IllegalArgumentException("Choose an eligible future15-minute to8-hour interval, mode, price and timezone");if(in.publish())auth.offer(who,"IR",in.mode());var prior=db.queryForList("SELECT id,ends_at,price_units,timezone,status FROM professional_availability_slots WHERE professional_user_id=? AND starts_at=? AND consultation_mode=? AND status<>'CANCELLED'",who,ProfessionalAuthority.time(in.startsAt()),in.mode());if(!prior.isEmpty()){var old=prior.getFirst();if(((java.sql.Timestamp)old.get("ends_at")).toInstant().equals(in.endsAt().truncatedTo(java.time.temporal.ChronoUnit.MICROS))&&((Number)old.get("price_units")).longValue()==in.priceUnits()&&in.timezone().equals(old.get("timezone"))&&(in.publish()!=old.get("status").equals("DRAFT")))return(UUID)old.get("id");throw new ConflictException("An interval already exists; publish/cancel that draft explicitly instead of replacing it");}if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM professional_calendar_exceptions WHERE professional_id=? AND active AND starts_at<? AND ends_at>?) OR EXISTS(SELECT 1 FROM professional_availability_slots WHERE professional_user_id=? AND status IN('AVAILABLE','BOOKED') AND starts_at<? AND ends_at>?)",Boolean.class,who,ProfessionalAuthority.time(in.endsAt()),ProfessionalAuthority.time(in.startsAt()),who,ProfessionalAuthority.time(in.endsAt()),ProfessionalAuthority.time(in.startsAt()))))throw new ConflictException("This interval conflicts with availability, a reservation or an exception");return db.queryForObject("INSERT INTO professional_availability_slots(id,professional_user_id,starts_at,ends_at,consultation_mode,status,governed,price_units,timezone,calendar_rule_id) VALUES(uuidv7(),?,?,?,?,?,TRUE,?,?,?) RETURNING id",UUID.class,who,ProfessionalAuthority.time(in.startsAt()),ProfessionalAuthority.time(in.endsAt()),in.mode(),in.publish()?"AVAILABLE":"DRAFT",in.priceUnits(),in.timezone(),rule);}
 public void publish(UUID who,UUID id,long revision){auth.owner(who);auth.lock(who);var rows=db.queryForList("SELECT * FROM professional_availability_slots WHERE id=? AND professional_user_id=? FOR UPDATE",id,who);if(rows.isEmpty())throw new NotFoundException("Own availability was not found");var slot=rows.getFirst();auth.offer(who,"IR",slot.get("consultation_mode").toString());if("AVAILABLE".equals(slot.get("status")))return;if(!"DRAFT".equals(slot.get("status"))||((Number)slot.get("revision")).longValue()!=revision)throw new ConflictException("Availability changed; reload");if(((java.sql.Timestamp)slot.get("starts_at")).toInstant().isBefore(Instant.now().plusSeconds(lead*60L)))throw new ConflictException("Minimum appointment lead time is required");if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM professional_calendar_exceptions WHERE professional_id=? AND active AND starts_at<? AND ends_at>?) OR EXISTS(SELECT 1 FROM professional_availability_slots WHERE professional_user_id=? AND id<>? AND status IN('AVAILABLE','BOOKED') AND starts_at<? AND ends_at>?)",Boolean.class,who,slot.get("ends_at"),slot.get("starts_at"),who,id,slot.get("ends_at"),slot.get("starts_at"))))throw new ConflictException("Availability conflicts with an exception or another reservation");db.update("UPDATE professional_availability_slots SET status='AVAILABLE',revision=revision+1 WHERE id=?",id);}
 public void cancelSlot(UUID who,UUID id,long revision){auth.owner(who);auth.lock(who);var rows=db.queryForList("SELECT status,revision FROM professional_availability_slots WHERE id=? AND professional_user_id=? FOR UPDATE",id,who);if(rows.isEmpty())throw new NotFoundException("Own availability was not found");var slot=rows.getFirst();if("CANCELLED".equals(slot.get("status")))return;if(!Set.of("DRAFT","AVAILABLE").contains(slot.get("status"))||((Number)slot.get("revision")).longValue()!=revision)throw new ConflictException("Reservations need an explicit appointment cancellation; reload current state");db.update("UPDATE professional_availability_slots SET status='CANCELLED',revision=revision+1 WHERE id=?",id);}
 public UUID rule(UUID who,Rule in){auth.owner(who);auth.lock(who);ZoneId.of(in.timezone());LocalTime start=LocalTime.parse(in.startsLocal()),end=LocalTime.parse(in.endsLocal());if(in.validFrom()==null||in.validUntil()==null||in.validUntil().isBefore(in.validFrom())||in.validUntil().isAfter(in.validFrom().plusDays(366))||!end.isAfter(start)||in.weekday()<1||in.weekday()>7||in.slotMinutes()<15||in.slotMinutes()>240||in.priceUnits()<0||!Set.of("TEXT","AUDIO","VIDEO").contains(in.mode())||!Set.of("EARLIER","LATER","REJECT").contains(in.overlapPolicy()))throw new IllegalArgumentException("Invalid bounded recurring schedule");if(db.queryForObject("SELECT count(*) FROM professional_calendar_rules WHERE professional_id=? AND active",Integer.class,who)>=28)throw new ConflictException("At most28 active recurring intervals");return db.queryForObject("INSERT INTO professional_calendar_rules(professional_id,timezone,weekday,starts_local,ends_local,valid_from,valid_until,slot_minutes,mode,price_units,overlap_policy) VALUES(?,?,?,?,?,?,?,?,?,?,?) RETURNING id",UUID.class,who,in.timezone(),in.weekday(),start,end,in.validFrom(),in.validUntil(),in.slotMinutes(),in.mode(),in.priceUnits(),in.overlapPolicy());}
 public static Optional<Instant> resolve(LocalDateTime local,ZoneId zone,String policy){var offsets=zone.getRules().getValidOffsets(local);if(offsets.isEmpty()||(offsets.size()>1&&"REJECT".equals(policy)))return Optional.empty();return Optional.of(local.toInstant(offsets.get("LATER".equals(policy)?offsets.size()-1:0)));}
 public Map<String,Object> materialize(UUID who,UUID id,boolean publish){auth.owner(who);auth.lock(who);var rules=db.queryForList("SELECT * FROM professional_calendar_rules WHERE id=? AND professional_id=? AND active FOR UPDATE",id,who);if(rules.isEmpty())throw new NotFoundException("Recurring schedule was not found");var r=rules.getFirst();ZoneId zone=ZoneId.of((String)r.get("timezone"));LocalDate from=((java.sql.Date)r.get("valid_from")).toLocalDate(),until=((java.sql.Date)r.get("valid_until")).toLocalDate(),today=LocalDate.now(zone);from=from.isBefore(today)?today:from;until=until.isAfter(today.plusDays(30))?today.plusDays(30):until;LocalTime start=((java.sql.Time)r.get("starts_local")).toLocalTime(),end=((java.sql.Time)r.get("ends_local")).toLocalTime();int minutes=((Number)r.get("slot_minutes")).intValue(),created=0,skipped=0;for(LocalDate day=from;!day.isAfter(until);day=day.plusDays(1)){if(day.getDayOfWeek().getValue()!=((Number)r.get("weekday")).intValue())continue;for(LocalTime time=start;!time.plusMinutes(minutes).isAfter(end)&&time.plusMinutes(minutes).isAfter(time);time=time.plusMinutes(minutes)){LocalDateTime local=day.atTime(time);var resolved=resolve(local,zone,r.get("overlap_policy").toString());if(resolved.isEmpty()){skipped++;continue;}Instant begins=resolved.get(),ends=begins.plusSeconds(minutes*60L);if(begins.isBefore(Instant.now().plusSeconds(lead*60L))){skipped++;continue;}var existing=db.queryForList("SELECT id,status,revision,calendar_rule_id FROM professional_availability_slots WHERE professional_user_id=? AND starts_at=? AND consultation_mode=? AND status<>'CANCELLED'",who,ProfessionalAuthority.time(begins),r.get("mode"));if(!existing.isEmpty()){var old=existing.getFirst();if(publish&&"DRAFT".equals(old.get("status"))&&id.equals(old.get("calendar_rule_id"))){publish(who,(UUID)old.get("id"),((Number)old.get("revision")).longValue());created++;}else skipped++;continue;}if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM professional_availability_slots WHERE professional_user_id=? AND starts_at=? AND consultation_mode=? AND status<>'CANCELLED') OR EXISTS(SELECT 1 FROM professional_calendar_exceptions WHERE professional_id=? AND active AND starts_at<? AND ends_at>?)",Boolean.class,who,ProfessionalAuthority.time(begins),r.get("mode"),who,ProfessionalAuthority.time(ends),ProfessionalAuthority.time(begins)))){skipped++;continue;}insert(who,new Slot(begins,ends,(String)r.get("mode"),((Number)r.get("price_units")).longValue(),zone.getId(),publish),id);created++;}}return Map.of("created",created,"skipped",skipped,"horizonDays",30,"minimumLeadMinutes",lead);}
 public UUID exception(UUID who,ExceptionWindow in){auth.owner(who);auth.lock(who);ProfessionalAuthority.text(in.reason(),300);if(in.startsAt()==null||in.endsAt()==null||!in.endsAt().isAfter(in.startsAt())||in.endsAt().isAfter(in.startsAt().plus(Duration.ofDays(31))))throw new IllegalArgumentException("Choose an unavailable interval of at most31 days");if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM professional_availability_slots WHERE professional_user_id=? AND status='BOOKED' AND starts_at<? AND ends_at>?)",Boolean.class,who,ProfessionalAuthority.time(in.endsAt()),ProfessionalAuthority.time(in.startsAt()))))throw new ConflictException("Reserved appointments require explicit cancellation/rescheduling; they are preserved");UUID id=db.queryForObject("INSERT INTO professional_calendar_exceptions(professional_id,starts_at,ends_at,reason) VALUES(?,?,?,?) RETURNING id",UUID.class,who,ProfessionalAuthority.time(in.startsAt()),ProfessionalAuthority.time(in.endsAt()),in.reason());db.update("UPDATE professional_availability_slots SET status='CANCELLED',revision=revision+1 WHERE professional_user_id=? AND status IN('DRAFT','AVAILABLE') AND starts_at<? AND ends_at>?",who,ProfessionalAuthority.time(in.endsAt()),ProfessionalAuthority.time(in.startsAt()));return id;}
 public void cancelRule(UUID who,UUID id){auth.owner(who);auth.lock(who);if(db.update("UPDATE professional_calendar_rules SET active=FALSE,revision=revision+1 WHERE professional_id=? AND id=? AND active",who,id)!=1)throw new NotFoundException("Recurring schedule was not found");db.update("UPDATE professional_availability_slots SET status='CANCELLED',revision=revision+1 WHERE calendar_rule_id=? AND status IN('DRAFT','AVAILABLE')",id);}
 public void checkin(UUID who,UUID session,UUID appointment){auth.actor(who);var rows=db.queryForList("SELECT c.*,s.ends_at FROM consultation_requests c JOIN professional_availability_slots s ON s.id=c.availability_slot_id WHERE c.id=? AND (c.requester_user_id=? OR c.professional_user_id=?) FOR UPDATE OF c",appointment,who,who);if(rows.isEmpty())throw new NotFoundException("Appointment was not found");var c=rows.getFirst();access.requireCare((UUID)c.get("requester_user_id"),(UUID)c.get("professional_user_id"),c.get("consultation_mode").toString());auth.offer((UUID)c.get("professional_user_id"),"IR",c.get("consultation_mode").toString());if(!Set.of("CONFIRMED").contains(c.get("status")))throw new ConflictException("Only a confirmed appointment can check in");Instant start=((java.sql.Timestamp)c.get("scheduled_at")).toInstant(),end=((java.sql.Timestamp)c.get("ends_at")).toInstant();if(Instant.now().isBefore(start.minusSeconds(900))||!Instant.now().isBefore(end))throw new ConflictException("Check-in opens15 minutes before the appointment");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM user_sessions WHERE id=? AND user_id=? AND revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP AND overall_expires_at>CURRENT_TIMESTAMP AND idle_expires_at>CURRENT_TIMESTAMP)",Boolean.class,session,who)))throw new ForbiddenException("A current authenticated session is required");db.update("INSERT INTO professional_appointment_readiness(appointment_id,actor_id,session_id,expires_at) VALUES(?,?,?,CURRENT_TIMESTAMP+INTERVAL '60 seconds') ON CONFLICT(appointment_id,actor_id) DO UPDATE SET session_id=EXCLUDED.session_id,observed_at=CURRENT_TIMESTAMP,expires_at=EXCLUDED.expires_at",appointment,who,session);}
 public Map<String,Object> readiness(UUID who,UUID appointment){auth.actor(who);var rows=db.queryForList("SELECT id,professional_user_id,scheduled_at,status FROM consultation_requests WHERE id=? AND (requester_user_id=? OR professional_user_id=?)",appointment,who,who);if(rows.isEmpty())throw new NotFoundException("Appointment was not found");var result=rows.getFirst();result.put("professionalReady",db.queryForObject("SELECT professional_qualification_live(?) AND EXISTS(SELECT 1 FROM professional_appointment_readiness p JOIN user_sessions s ON s.id=p.session_id WHERE p.appointment_id=? AND p.actor_id=? AND p.expires_at>CURRENT_TIMESTAMP AND s.revoked_at IS NULL AND s.expires_at>CURRENT_TIMESTAMP AND s.overall_expires_at>CURRENT_TIMESTAMP AND s.idle_expires_at>CURRENT_TIMESTAMP)",Boolean.class,result.get("professional_user_id"),appointment,result.get("professional_user_id")));result.put("scope","Recent authenticated readiness is not evidence of a delivered consultation or a no-show decision.");return result;}
}
